<script setup>
import { computed, nextTick, onMounted, reactive, ref, toRaw, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';

import { apiClient, authSession } from '../lib/auth/index.js';
import { reportingStateFromQuery, reportingQueryFor, REPORTING_TABS } from '../lib/search/reporting-deep-link.js';
import { searchResultLink } from '../lib/search/enterprise-search.js';

const route = useRoute(); const router = useRouter(); const initial = reportingStateFromQuery(route.query);
const emptyWorkspace = () => ({ canManage: false, datasetColumns: {}, latestSnapshots: {}, projects: [], reports: [], runs: [], subscriptions: [], total: 0, views: [] });
const workspace = ref(emptyWorkspace()); const dashboards = ref(null); const searchResults = ref({ facetCounts: {}, records: [], total: 0 }); const loading = ref(true); const errorMessage = ref(''); const activeTab = ref(initial.tab);
const filters = reactive({ limit: 25, offset: 0, projectId: initial.projectId, query: '', status: '' }); const appliedProjectId = ref(initial.projectId);
const sourceProject = computed(() => (appliedProjectId.value ? workspace.value.projects.find((item) => item.id === appliedProjectId.value) ?? null : null));
// The project and tab live in the URL, so /reports?projectId=…&tab=… links open them directly.
function syncUrl() { const query = reportingQueryFor(route.query, { projectId: appliedProjectId.value, tab: activeTab.value }); if (query.projectId !== route.query.projectId || query.tab !== route.query.tab) router.replace({ query }); }
function selectTab(tab) { activeTab.value = tab; syncUrl(); }
watch(() => [route.query.projectId, route.query.tab], () => { const next = reportingStateFromQuery(route.query); activeTab.value = next.tab; if (next.projectId !== appliedProjectId.value) { appliedProjectId.value = next.projectId; filters.projectId = next.projectId; filters.offset = 0; load(); } }); const search = reactive({ facets: '', limit: 25, offset: 0, projectId: '', query: '', types: '' }); const searchedQuery = ref('');
const editor = reactive({ kind: '', mode: 'create', recordId: '', values: {} }); const editorDialog = ref(null); const deleteTarget = reactive({ id: '', kind: '', title: '', version: 0 }); const deleteDialog = ref(null);
const runResult = ref(null); const resultDialog = ref(null); const token = computed(() => authSession.state.token); const reportMap = computed(() => new Map(workspace.value.reports.map((item) => [item.id, item]))); const projectMap = computed(() => new Map(workspace.value.projects.map((item) => [item.id, item])));
const pages = computed(() => Math.max(1, Math.ceil(workspace.value.total / filters.limit))); const page = computed(() => Math.floor(filters.offset / filters.limit) + 1);
async function load() { loading.value = true; errorMessage.value = ''; try { [workspace.value, dashboards.value] = await Promise.all([apiClient.getReportingWorkspace(filters, token.value), apiClient.getStandardDashboards(filters.projectId, token.value)]); } catch (error) { errorMessage.value = error.message ?? 'Unable to load reporting workspace.'; } finally { loading.value = false; } }
async function runSearch() { errorMessage.value = ''; searchedQuery.value = search.query.trim(); if (!searchedQuery.value) { searchResults.value = { facetCounts: {}, records: [], total: 0 }; return; } try { searchResults.value = await apiClient.searchEnterprise(search, token.value); } catch (error) { errorMessage.value = error.message ?? 'Unable to search enterprise context.'; } }
async function refreshSearch() { try { await apiClient.refreshEnterpriseSearch(token.value); await runSearch(); } catch (error) { errorMessage.value = error.message ?? 'Unable to refresh search index.'; } }
function blank(kind) {
  if (kind === 'report') return { columns: ['projectId', 'projectName', 'status'], dataset: 'project', description: '', filtersText: '{}', groupByText: '', name: '', projectId: filters.projectId || null, status: 'active', visibility: 'private', visualization: 'table' };
  if (kind === 'view') return { columnsText: '', filtersText: '{}', name: '', projectId: filters.projectId || null, sortText: '', surface: 'global_search', visibility: 'private' };
  const tomorrow = new Date(Date.now() + 86_400_000).toISOString().slice(0, 16); return { deliveryChannel: 'in_app', enabled: true, format: 'csv', intervalMinutes: 1440, nextRunAt: tomorrow, recipientsText: '', reportId: workspace.value.reports[0]?.id ?? '', timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC' };
}
async function openEditor(kind, record = null) { editor.kind = kind; editor.mode = record ? 'edit' : 'create'; editor.recordId = record?.id ?? ''; editor.values = record ? structuredClone(toRaw(record)) : blank(kind); if (record && kind === 'report') { editor.values.filtersText = JSON.stringify(record.filters); editor.values.groupByText = record.groupBy.join(', '); } if (record && kind === 'view') { editor.values.filtersText = JSON.stringify(record.filters); editor.values.columnsText = record.columns.join(', '); editor.values.sortText = record.sort.map((item) => `${item.field}:${item.direction}`).join(', '); } if (record && kind === 'subscription') { editor.values.intervalMinutes = record.schedule.intervalMinutes; editor.values.timezone = record.schedule.timezone; editor.values.recipientsText = record.recipients.join(', '); editor.values.nextRunAt = String(record.nextRunAt).slice(0, 16); } await nextTick(); editorDialog.value?.showModal(); }
function changeReportDataset() { editor.values.columns = (workspace.value.datasetColumns[editor.values.dataset] ?? []).slice(0, 3); editor.values.groupByText = ''; }
function changeReportProjectScope() { if (!editor.values.projectId && editor.values.visibility === 'project') editor.values.visibility = 'private'; }
function closeEditor() { editorDialog.value?.close(); }
function payload() { const values = { ...editor.values }; for (const key of ['createdAt', 'updatedAt', 'tenantId', 'ownerUserId', 'id', 'lastRunAt']) delete values[key]; if (editor.mode === 'edit') values.expectedVersion = editor.values.version; delete values.version;
  if (editor.kind === 'report') { values.filters = JSON.parse(values.filtersText || '{}'); values.groupBy = values.groupByText.split(',').map((item) => item.trim()).filter(Boolean); delete values.filtersText; delete values.groupByText; }
  if (editor.kind === 'view') { values.filters = JSON.parse(values.filtersText || '{}'); values.columns = values.columnsText.split(',').map((item) => item.trim()).filter(Boolean); values.sort = values.sortText.split(',').map((item) => { const [field, direction] = item.split(':'); return { direction: direction === 'desc' ? 'desc' : 'asc', field: field.trim() }; }).filter((item) => item.field); delete values.filtersText; delete values.columnsText; delete values.sortText; }
  if (editor.kind === 'subscription') { values.nextRunAt = new Date(values.nextRunAt).toISOString(); values.recipients = values.recipientsText.split(',').map((item) => item.trim()).filter(Boolean); values.schedule = { intervalMinutes: Number(values.intervalMinutes), timezone: values.timezone }; delete values.intervalMinutes; delete values.timezone; delete values.recipientsText; }
  return values; }
async function saveEditor() { try { const values = payload(); const edit = editor.mode === 'edit'; if (editor.kind === 'report') edit ? await apiClient.updateReportDefinition(editor.recordId, values, token.value) : await apiClient.createReportDefinition(values, token.value); if (editor.kind === 'view') edit ? await apiClient.updateSavedView(editor.recordId, values, token.value) : await apiClient.createSavedView(values, token.value); if (editor.kind === 'subscription') edit ? await apiClient.updateReportSubscription(editor.recordId, values, token.value) : await apiClient.createReportSubscription(values, token.value); closeEditor(); await load(); } catch (error) { errorMessage.value = error.message ?? 'Unable to save reporting record.'; } }
async function openDelete(kind, record, title) { Object.assign(deleteTarget, { id: record.id, kind, title, version: record.version }); await nextTick(); deleteDialog.value?.showModal(); }
async function deleteRecord() { try { const { id, kind, version } = deleteTarget; if (kind === 'report') await apiClient.deleteReportDefinition(id, version, token.value); if (kind === 'view') await apiClient.deleteSavedView(id, version, token.value); if (kind === 'subscription') await apiClient.deleteReportSubscription(id, version, token.value); deleteDialog.value?.close(); await load(); } catch (error) { errorMessage.value = error.message ?? 'Unable to delete reporting record.'; deleteDialog.value?.close(); } }
async function executeReport(report, format = 'json') { try { const result = await apiClient.runReport(report.id, { format, limit: 1000, parameters: {} }, token.value); if (format === 'json') { runResult.value = { report, result }; await nextTick(); resultDialog.value?.showModal(); } else { const bytes = result.contentEncoding === 'base64' ? Uint8Array.from(atob(result.content), (character) => character.charCodeAt(0)) : new TextEncoder().encode(result.content); const url = URL.createObjectURL(new Blob([bytes], { type: result.contentType })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = result.filename; anchor.click(); URL.revokeObjectURL(url); await load(); } } catch (error) { errorMessage.value = error.message ?? 'Unable to run report.'; } }
function applyFilters() { filters.offset = 0; appliedProjectId.value = filters.projectId; syncUrl(); load(); } function changePage(delta) { filters.offset = Math.max(0, Math.min((pages.value - 1) * filters.limit, filters.offset + delta * filters.limit)); load(); }
function entries(value) { return Object.entries(value ?? {}); } function number(value) { return Number(value ?? 0).toLocaleString(); } function dateTime(value) { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'; }
// Searches rebuild a stale index themselves, so opening the page no longer refreshes it.
onMounted(load);
</script>

<template>
  <main class="reporting-page"><header class="reporting-header"><div><h1>Search & reporting</h1><p>Permission-aware enterprise search, dashboards, custom reports, BI feeds, and scheduled delivery.</p></div><div class="header-actions"><button class="btn btn-sm btn-primary" type="button" @click="openEditor('report')">New report</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="load">Refresh</button></div></header>
    <div v-if="sourceProject" class="reporting-source" role="note"><i class="bi bi-kanban" aria-hidden="true"></i><span>Showing <strong>{{ sourceProject.name }}</strong>. New reports default to this project.</span><RouterLink :to="{ name: 'project-insights', params: { projectId: sourceProject.id } }"><i class="bi bi-arrow-left" aria-hidden="true"></i> Back to project Insights</RouterLink></div>
    <div v-if="errorMessage" class="alert alert-danger" role="alert">{{ errorMessage }}</div>
    <form class="reporting-filters" @submit.prevent="applyFilters"><label>Find reports<input v-model="filters.query" placeholder="Name or description" /></label><label>Project<select v-model="filters.projectId"><option value="">All visible projects</option><option v-for="item in workspace.projects" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Status<select v-model="filters.status"><option value="">Any status</option><option value="active">Active</option><option value="inactive">Inactive</option></select></label><button class="btn btn-sm btn-outline-secondary">Apply</button></form>
    <nav class="reporting-tabs" aria-label="Search and reporting sections"><button v-for="tab in REPORTING_TABS" :key="tab" :class="{ active: activeTab === tab }" :aria-current="activeTab === tab ? 'page' : undefined" type="button" @click="selectTab(tab)">{{ tab }}</button></nav>
    <p v-if="loading" class="empty-state" role="status">Loading reporting workspace…</p>
    <template v-else>
      <section v-if="activeTab === 'dashboards'" aria-labelledby="dashboard-title"><div class="section-heading"><h2 id="dashboard-title">Standard enterprise dashboards</h2><small>As of {{ dateTime(dashboards?.asOf) }} · row-level secured</small></div><div class="dashboard-grid">
        <article><h3>Executive</h3><strong>{{ number(dashboards?.executive.projectCount) }}</strong><span>visible projects</span><dl><template v-for="[key,value] in entries(dashboards?.executive.byStatus)" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></template></dl></article>
        <article><h3>Portfolio</h3><strong>{{ number(dashboards?.portfolio.alignmentCount) }}</strong><span>alignments</span><p>{{ number(dashboards?.portfolio.benefitValue) }} recorded benefit</p></article>
        <article><h3>Project delivery</h3><strong>{{ number(dashboards?.project.workItemCount) }}</strong><span>work items</span><p>{{ number(dashboards?.project.epicCount) }} epics · {{ number(dashboards?.project.storyCount) }} stories · {{ number(dashboards?.project.taskCount) }} tasks</p></article>
        <article><h3>Sprints</h3><strong>{{ number(dashboards?.sprint.activeCount) }}</strong><span>active of {{ number(dashboards?.sprint.total) }}</span></article>
        <article><h3>Resources</h3><strong>{{ number(dashboards?.resource.averageUtilizationPercent) }}%</strong><span>average utilization</span><p>{{ number(dashboards?.resource.overallocatedCount) }} overallocated</p></article>
        <article><h3>Financials</h3><template v-if="dashboards?.financial.authorized"><dl><template v-for="[key,value] in entries(dashboards?.financial.byKind)" :key="key"><dt>{{ key.replace('_',' ') }}</dt><dd>{{ number(value) }}</dd></template></dl></template><p v-else>Manager access required.</p></article>
        <article><h3>Risk</h3><strong>{{ number(dashboards?.risk.openCount) }}</strong><span>open · {{ number(dashboards?.risk.criticalOpenCount) }} critical</span></article>
        <article><h3>Agent governance</h3><strong>{{ number(dashboards?.agentGovernance.activeGoalCount) }}</strong><span>active goals</span><p>{{ number(dashboards?.agentGovernance.unreadNotificationCount) }} unread attention records</p></article>
        <article><h3>Workflow</h3><strong>{{ number(dashboards?.workflow.pendingApprovalCount) }}</strong><span>pending approvals</span><p>{{ number(dashboards?.workflow.overdueSlaCount) }} overdue SLA</p></article>
      </div></section>
      <section v-if="activeTab === 'search'" aria-labelledby="search-title"><div class="section-heading"><h2 id="search-title">Indexed enterprise search</h2><button v-if="workspace.canManage" class="btn btn-sm btn-outline-secondary" type="button" @click="refreshSearch()">Refresh index</button></div><form class="search-form" @submit.prevent="runSearch"><label>Search<input v-model="search.query" required /></label><label>Types<input v-model="search.types" placeholder="project,risk,task" /></label><label>Facets<input v-model="search.facets" placeholder="status:open,impact:high" /></label><button class="btn btn-sm btn-primary">Search</button></form><p v-if="!searchedQuery" class="empty-state">Enter a word or phrase to search projects, work items, risks, milestones and portfolio records you can access.</p><template v-else><p>{{ number(searchResults.total) }} result(s)</p><div class="search-results"><article v-for="item in searchResults.records" :key="item.id"><div><span>{{ item.documentType }}</span><h3><RouterLink :to="searchResultLink(item)">{{ item.title }}</RouterLink></h3></div><small>{{ item.facets }}</small><p>{{ item.content.slice(0,220) }}</p></article><p v-if="!searchResults.records.length" class="empty-state">No authorized search results.</p></div></template></section>
      <section v-if="activeTab === 'reports'" aria-labelledby="reports-title"><div class="section-heading"><h2 id="reports-title">Custom reports & dashboards</h2><button class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('report')">Add report</button></div><div class="report-grid"><article v-for="item in workspace.reports" :key="item.id"><div><small>{{ item.dataset.replace('_',' ') }} · {{ item.visibility }}</small><h3>{{ item.name }}</h3></div><span>{{ item.status }}</span><p>{{ item.description || `${item.columns.length} selected columns` }}</p><div class="report-actions"><button class="btn btn-sm btn-primary" type="button" @click="executeReport(item)">Run</button><div class="dropdown"><button class="btn btn-sm btn-outline-secondary dropdown-toggle" type="button" data-bs-toggle="dropdown">Export</button><ul class="dropdown-menu"><li v-for="format in ['csv','xlsx','pdf']" :key="format"><button class="dropdown-item" type="button" @click="executeReport(item, format)">{{ format.toUpperCase() }}</button></li></ul></div><button class="icon-btn" aria-label="Edit report" type="button" @click="openEditor('report', item)"><i class="bi bi-pencil"></i></button><button class="icon-btn" aria-label="Delete report" type="button" @click="openDelete('report', item, item.name)"><i class="bi bi-trash"></i></button></div></article><p v-if="!workspace.reports.length" class="empty-state">No reports match the filters.</p></div></section>
      <section v-if="activeTab === 'views'" aria-labelledby="views-title"><div class="section-heading"><h2 id="views-title">Saved searches & views</h2><button class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('view')">Add view</button></div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Name</th><th>Surface</th><th>Scope</th><th>Visibility</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.views" :key="item.id"><td>{{ item.name }}</td><td>{{ item.surface.replace('_',' ') }}</td><td>{{ projectMap.get(item.projectId)?.name ?? 'Tenant' }}</td><td>{{ item.visibility }}</td><td><button class="icon-btn" aria-label="Edit saved view" type="button" @click="openEditor('view', item)"><i class="bi bi-pencil"></i></button><button class="icon-btn" aria-label="Delete saved view" type="button" @click="openDelete('view', item, item.name)"><i class="bi bi-trash"></i></button></td></tr></tbody></table></div></section>
      <section v-if="activeTab === 'subscriptions'" aria-labelledby="subscriptions-title"><div class="section-heading"><h2 id="subscriptions-title">Scheduled delivery</h2><button class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('subscription')">Add subscription</button></div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Report</th><th>Channel / format</th><th>Next run</th><th>Schedule</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.subscriptions" :key="item.id"><td>{{ reportMap.get(item.reportId)?.name ?? item.reportId }}</td><td>{{ item.deliveryChannel }} · {{ item.format.toUpperCase() }}</td><td>{{ dateTime(item.nextRunAt) }}</td><td>Every {{ item.schedule.intervalMinutes }} min · {{ item.schedule.timezone }}</td><td>{{ item.enabled ? 'Enabled' : 'Paused' }}</td><td><button class="icon-btn" aria-label="Edit subscription" type="button" @click="openEditor('subscription', item)"><i class="bi bi-pencil"></i></button><button class="icon-btn" aria-label="Delete subscription" type="button" @click="openDelete('subscription', item, reportMap.get(item.reportId)?.name ?? item.id)"><i class="bi bi-trash"></i></button></td></tr></tbody></table></div></section>
      <section v-if="activeTab === 'runs'" aria-labelledby="runs-title"><div class="section-heading"><h2 id="runs-title">Execution & snapshot history</h2></div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Started</th><th>Report</th><th>Format</th><th>Rows</th><th>Status</th><th>Error</th></tr></thead><tbody><tr v-for="item in workspace.runs" :key="item.id"><td>{{ dateTime(item.startedAt) }}</td><td>{{ reportMap.get(item.reportId)?.name ?? item.reportId }}</td><td>{{ item.format }}</td><td>{{ item.rowCount }}</td><td>{{ item.status }}</td><td>{{ item.error || '—' }}</td></tr></tbody></table></div></section>
    </template>
    <footer class="pagination"><button class="btn btn-sm btn-outline-secondary" :disabled="page===1" @click="changePage(-1)">Previous</button><span>Page {{ page }} of {{ pages }}</span><button class="btn btn-sm btn-outline-secondary" :disabled="page===pages" @click="changePage(1)">Next</button></footer>

    <dialog ref="editorDialog" class="report-dialog" @cancel.prevent="closeEditor"><form method="dialog" @submit.prevent="saveEditor"><header><h2>{{ editor.mode === 'edit' ? 'Edit' : 'Add' }} {{ editor.kind }}</h2><button aria-label="Close editor" type="button" @click="closeEditor"><i class="bi bi-x-lg"></i></button></header>
      <template v-if="editor.kind === 'report'"><label>Name<input v-model="editor.values.name" required /></label><label>Description<textarea v-model="editor.values.description"></textarea></label><div class="dialog-grid"><label>Dataset<select v-model="editor.values.dataset" @change="changeReportDataset"><option v-for="dataset in Object.keys(workspace.datasetColumns)" :key="dataset" :value="dataset">{{ dataset.replace('_',' ') }}</option></select></label><label>Visualization<select v-model="editor.values.visualization"><option v-for="kind in ['table','summary','bar','line','pie']" :key="kind">{{ kind }}</option></select></label><label>Project scope<select v-model="editor.values.projectId" @change="changeReportProjectScope"><option :value="null">All visible projects</option><option v-for="item in workspace.projects" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Visibility<select v-model="editor.values.visibility"><option value="private">Private</option><option v-if="editor.values.projectId" value="project">Project</option><option v-if="workspace.canManage" value="tenant">Tenant</option></select></label><label>Status<select v-model="editor.values.status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label></div><fieldset><legend>Columns</legend><label v-for="column in workspace.datasetColumns[editor.values.dataset] ?? []" :key="column" class="check"><input v-model="editor.values.columns" type="checkbox" :value="column" /> {{ column }}</label></fieldset><label>Filters JSON<textarea v-model="editor.values.filtersText" class="code-input"></textarea></label><label>Group by <small>Comma separated</small><input v-model="editor.values.groupByText" /></label></template>
      <template v-if="editor.kind === 'view'"><label>Name<input v-model="editor.values.name" required /></label><div class="dialog-grid"><label>Surface<select v-model="editor.values.surface"><option v-for="kind in ['global_search','projects','portfolio','resources','workflows','governance','reports']" :key="kind" :value="kind">{{ kind.replace('_',' ') }}</option></select></label><label>Project scope<select v-model="editor.values.projectId"><option :value="null">Tenant</option><option v-for="item in workspace.projects" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Visibility<select v-model="editor.values.visibility"><option value="private">Private</option><option v-if="editor.values.projectId" value="project">Project</option><option v-if="workspace.canManage" value="tenant">Tenant</option></select></label></div><label>Filters JSON<textarea v-model="editor.values.filtersText" class="code-input"></textarea></label><label>Columns <small>Comma separated</small><input v-model="editor.values.columnsText" /></label><label>Sort <small>field:asc, field:desc</small><input v-model="editor.values.sortText" /></label></template>
      <template v-if="editor.kind === 'subscription'"><label>Report<select v-model="editor.values.reportId" required><option v-for="item in workspace.reports" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><div class="dialog-grid"><label>Channel<select v-model="editor.values.deliveryChannel"><option value="in_app">In app</option><option value="email">Email</option></select></label><label>Format<select v-model="editor.values.format"><option v-for="format in ['csv','xlsx','pdf','json']" :key="format">{{ format }}</option></select></label><label>Next run<input v-model="editor.values.nextRunAt" type="datetime-local" required /></label><label>Interval minutes<input v-model.number="editor.values.intervalMinutes" min="15" max="525600" type="number" /></label><label>Timezone<input v-model="editor.values.timezone" required /></label><label class="check"><input v-model="editor.values.enabled" type="checkbox" /> Enabled</label></div><label v-if="editor.values.deliveryChannel==='email'">Recipients <small>Comma separated</small><input v-model="editor.values.recipientsText" required /></label></template>
      <footer><button class="btn btn-sm btn-outline-secondary" type="button" @click="closeEditor">Cancel</button><button class="btn btn-sm btn-primary">Save</button></footer></form></dialog>
    <dialog ref="resultDialog" class="report-dialog"><form method="dialog"><header><h2>{{ runResult?.report.name }}</h2><button aria-label="Close result" type="button" @click="resultDialog.close()"><i class="bi bi-x-lg"></i></button></header><p>{{ runResult?.result.rows.length }} rows · as of {{ dateTime(runResult?.result.freshness.asOf) }}</p><div class="table-responsive"><table class="table table-sm"><thead><tr><th v-for="column in runResult?.report.columns" :key="column">{{ column }}</th></tr></thead><tbody><tr v-for="(row,index) in runResult?.result.rows" :key="index"><td v-for="column in runResult?.report.columns" :key="column">{{ row[column] }}</td></tr></tbody></table></div><footer><button class="btn btn-sm btn-primary">Close</button></footer></form></dialog>
    <dialog ref="deleteDialog" class="report-dialog report-dialog--small"><form method="dialog" @submit.prevent="deleteRecord"><header><h2>Delete {{ deleteTarget.kind }}</h2></header><p>Delete <strong>{{ deleteTarget.title }}</strong>? Subscribed reports must be unsubscribed first.</p><footer><button class="btn btn-sm btn-outline-secondary" type="button" @click="deleteDialog.close()">Cancel</button><button class="btn btn-sm btn-danger">Delete</button></footer></form></dialog>
  </main>
